"""Independent reliability reviewer for ARC-0012.

Adds one failure mode the path-completeness author list does not catch:
byte-stale generated files that still have a matching registry id.
Does NOT certify the 47-class enumeration complete; the cited prompt
file is absent.
"""
from __future__ import annotations

ADDED_MODE = {
    "id": "FM-STALE-BYTES",
    "title": "Path-complete stale generated bytes",
    "author_missed": True,
    "caught_by_direction_a": False,
    "caught_by_direction_b": False,
    "seeded_classes": ["stale-cache", "version-skew", "stale-evidence"],
    "description": (
        "A generated file sits at the exact path mapping.py names, with size > 0, "
        "so Direction A is silent and Direction B is silent. The bytes were emitted "
        "by generator vN-1 (or a wrong template) after the registry row changed. "
        "Path completeness is not freshness. The unit question asks what happens "
        "when the generator is wrong OR stale; stale-but-present is the stale half, "
        "and these two tests do not see it."
    ),
    "required_followup": (
        "Pair this gate with a provenance header (registry id + generator version "
        "+ input digest) inside every generated file, and a byte-compare of two "
        "regenerations (ARC-0010 / ARC-0015). Completeness stays; freshness is a "
        "different detector."
    ),
}


def review() -> dict:
    return {
        "reviewer_id": "ARC-0012-independent-reliability",
        "verdict": "PASS",
        "independent": True,
        "scope_not_agreement": True,
        "fresh_context": True,
        "enumeration_certified_against_47": False,
        "enumeration_certify_reason": (
            "The 47 seeded classes are cited as _USER-PROMPTS.md:11300-11347. "
            "That file is not on this worktree. Certifying completeness against "
            "an unread list would be overclaim. Instead the reviewer adds "
            "FM-STALE-BYTES, which the author's path-completeness list missed."
        ),
        "added_failure_mode": ADDED_MODE,
        "method": (
            "Reviewed the author's Direction A/B path gate and the live counts. "
            "Checked that empty files count as A, that combined counts are "
            "forbidden, and that detector-control known-orphans exist. Agreement "
            "with the 'fails Direction A today' verdict is not required for PASS; "
            "scope is: two counts, both-states, detector-control, one missed mode."
        ),
    }
